    static T Field<T>(object o,string key){return (T)o.GetType().GetField(key,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
    static void Call(object o,string key,params object[] args){o.GetType().GetMethod(key,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,args);}
    static IEnumerable<Control> All(Control c){foreach(Control x in c.Controls){yield return x;foreach(var y in All(x))yield return y;}}
    static void Save(Form form,string path){Application.DoEvents();using(var image=new System.Drawing.Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new System.Drawing.Rectangle(System.Drawing.Point.Empty,image.Size));image.Save(path);}}
    static void CheckActions(Control root,string state){foreach(var stage in All(root).OfType<StateStage>().Where(c=>c.Visible))foreach(var button in All(stage).OfType<Button>().Where(b=>b.Visible)){var point=stage.PointToClient(button.Parent.PointToScreen(button.Location));Check(point.X>=0&&point.X+button.Width<=stage.Width,"state action remains inside the stage: "+state+" / "+button.Text);Check(button.Right<=button.Parent.ClientSize.Width&&button.Bottom<=button.Parent.ClientSize.Height,"state action remains inside its container: "+state+" / "+button.Text+" bounds="+button.Bounds+" parent="+button.Parent.ClientSize);}}
    static void Check(bool value,string label){if(!value)throw new Exception(label);}
    static void Wait(MainWindow main){var until=DateTime.UtcNow.AddSeconds(20);do{Application.DoEvents();System.Threading.Thread.Sleep(20);}while((main.Busy||main.Reading||main.ModeSaving)&&DateTime.UtcNow<until);Check(!main.Busy&&!main.Reading&&!main.ModeSaving&&main.TestError==null,"request completes");}
    static void WaitUntil(Func<bool> ready,string label){var until=DateTime.UtcNow.AddSeconds(10);while(!ready()&&DateTime.UtcNow<until){Application.DoEvents();System.Threading.Thread.Sleep(5);}Check(ready(),label);}
    [STAThread]static int Main(string[] args){Application.EnableVisualStyles();Program.TestMode=true;string root=args[0],output=args[1];try{
        Check(MotionPaint.Ease(0)==0&&MotionPaint.Ease(1)==1,"animation settles exactly at both endpoints");byte[] before=File.ReadAllBytes(Path.Combine(root,"machines","test.json"));File.WriteAllBytes(Path.Combine(root,"machines","second.json"),before);
        using(var main=new MainWindow(root,null,false,false)){main.Backend=new Backend(root,args.Length>2?args[2]:null);main.Backend.Open();main.Show();Call(main,"Fill",main.Backend.Call("list"));Wait(main);
            var replayStage=Field<StateStage>(main,"machineStage");var stateWord=Field<TrackedWord>(replayStage,"word");Call(main,"SelectVm","test");int animation=stateWord.AnimationGeneration;Call(main,"SelectVm","second");Check(stateWord.AnimationGeneration==animation+1,"switching machines with the same state replays the stage word");Call(main,"SelectVm","second");Check(stateWord.AnimationGeneration==animation+1,"refreshing the same selected machine keeps the animation running");Call(main,"SelectVm","test");Check(stateWord.AnimationGeneration==animation+2,"returning to a machine replays its state word again");
            var service=All(main).OfType<Button>().Single(b=>b.Text=="Сервис");var brand=All(main).OfType<ReferenceBrand>().Single();Check(service.FindForm()==main&&service.Parent.Parent==brand.Parent,"service retains its handler in the main header");var servicePoint=brand.Parent.PointToClient(service.Parent.PointToScreen(service.Location));Check(servicePoint.X>=brand.Right&&servicePoint.Y>=brand.Top&&servicePoint.Y+service.Height<=brand.Bottom,"service sits to the right of QVM inside the header");Check(Math.Abs(servicePoint.Y+service.Height/2F-(brand.Top+brand.VisualCenterY))<=1,"service is centered on the visible QVM glyphs");Check(!Field<Label>(main,"breadcrumb").Visible&&Field<Label>(main,"footer").Text=="","idle breadcrumbs and footer caption are removed");Check(!All(main).OfType<Label>().Any(label=>label.Visible&&(label.Text=="01 / SYSTEM INDEX"||label.Text=="02 / STATE STAGE")),"decorative section captions are removed");
            Check(All(main).Where(c=>c.Visible).All(c=>c.Font.FontFamily.Name.StartsWith("Unbounded")),"main window uses embedded Unbounded");Check(All(main).OfType<Button>().Single(b=>b.Text=="Открыть консоль").Enabled==false,"unavailable console remains disabled rather than sending a VM command");
            using(var edit=new EditDialog(main,"test",main.Backend.Call("get",J.O("name","test")))){
                edit.Show(main);Application.DoEvents();var backdrop=main.Controls.OfType<ReferenceBackdropSurface>().Single();
