                Check(Object.ReferenceEquals(previousSnapshot,backdrop.Snapshot),"owner resize retains its previous snapshot while processing");
                WaitUntil(()=>backdrop.Generation>generation&&backdrop.Snapshot.Size==main.ClientSize,"owner resize refreshes the cached backdrop");
