                foreach(var page in deck.Pages){deck.SelectedPage=page;Application.DoEvents();Check(All(edit).Where(c=>c.Visible).All(c=>c.Font.FontFamily.Name.StartsWith("Unbounded")),"settings uses the original embedded Unbounded face");if(page.Text=="Аргументы QEMU")File.WriteAllLines(Path.Combine(output,"extra-layout-bounds.txt"),All(page).Select(c=>c.GetType().Name+" "+c.Text+" bounds="+c.Bounds+" min="+c.MinimumSize+" auto="+c.AutoSize));if(page.Text=="Справка QEMU"){var topics=Field<ThemedList>(All(edit).OfType<ExtraHelpView>().Single(),"topics");Check((int)typeof(ThemedList).GetProperty("ContentOffset",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(topics,null)==0,"first help topic remains fully visible after layout");}Save(edit,Path.Combine(output,"html-config-"+(deck.Pages.IndexOf(page)+1)+".png"));}
                var actual=edit.GetType().GetMethod("FieldsData",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(edit,null);Check(J.N(actual,"ram_mb")==J.N(J.V(main.Row("test"),"data"),"ram_mb"),"moving controls preserves RAM binding");
