                Check(All(create).OfType<FieldInput>().Contains(Field<FieldInput>(create,"name"))&&All(create).OfType<NumberInput>().Contains(Field<NumberInput>(create,"size")),"creation preserves name and disk size controls");Save(create,Path.Combine(output,"html-create-0.png"));foreach(var page in deck.Pages){deck.SelectedPage=page;Application.DoEvents();Save(create,Path.Combine(output,"html-create-page-"+(deck.Pages.IndexOf(page)+1)+".png"));}
                var json=Field<ThemedEditor>(create,"raw");var draft=J.D(J.Json().DeserializeObject(json.Text));draft["ram_mb"]=2048;draft["cores"]=3;json.Text=J.Json().Serialize(draft);deck.SelectedIndex=0;Application.DoEvents();Check(Field<NumberInput>(create,"ram").Value==2048&&Field<NumberInput>(create,"cores").Value==3,"creation JSON roundtrip retains resource bindings");
                deck.SelectedIndex=5;json.Text="{";deck.SelectedIndex=0;Check(deck.SelectedIndex==5,"invalid creation JSON blocks leaving its page");json.Text=J.Json().Serialize(draft);deck.SelectedIndex=0;main.TestError=null;
                create.Close();
            }
            using(var timer=new System.Windows.Forms.Timer{Interval=100}){timer.Tick+=(s,e)=>{var window=Application.OpenForms.Cast<Form>().FirstOrDefault(f=>f.Text=="Service · QemuM");if(window==null)return;timer.Stop();Check(All(window).OfType<ReferenceServiceTile>().Count()==4,"service has the four reference tiles");Check(!All(window).OfType<ReferenceServiceTile>().Single(t=>t.Text=="Настройки приложения").Enabled,"unsupported preferences cannot execute");Save(window,Path.Combine(output,"html-service-dialog.png"));window.Close();};timer.Start();Call(main,"ShowService");}
            using(var timer=new System.Windows.Forms.Timer{Interval=100}){timer.Tick+=(s,e)=>{var window=Application.OpenForms.Cast<Form>().FirstOrDefault(f=>f.Text=="Новый стенд");if(window==null)return;timer.Stop();var include=All(window).OfType<Button>().First(b=>b.Text=="Включить");include.PerformClick();Check(include.Text=="Включена"&&All(window).OfType<CheckBox>().Any(c=>c.Checked),"membership button retains the existing checkbox model");Save(window,Path.Combine(output,"html-stand-settings.png"));window.Close();};timer.Start();Call(main,"EditStand",new object[]{null});}
            var tabs=Field<WorkspaceTabs>(main,"workspace");main.Snapshots("test");Wait(main);Application.DoEvents();
            var snapshots=All(main).OfType<SnapshotCatalogView>().Single();Check(snapshots.Visible&&tabs.SelectedIndex==3,"snapshot catalog opens inside the main workspace");Check(!Application.OpenForms.OfType<SnapshotsWindow>().Any(),"regular snapshot navigation reuses a view without opening a window");Save(main,Path.Combine(output,"html-snapshots.png"));main.Snapshots("test");Check(Object.ReferenceEquals(snapshots,All(main).OfType<SnapshotCatalogView>().Single()),"repeated snapshot navigation reuses its catalog");
            tabs.SelectedIndex=1;Application.DoEvents();Check(All(main).OfType<AdapterCards>().Any(c=>c.Visible),"network has structured adapter cards");var settings=All(main).OfType<Button>().Single(b=>b.Text=="Настроить адаптеры");Check(settings.Visible&&!All(All(main).OfType<AdapterCards>().Single()).Contains(settings),"network action is pinned outside scrolling content");var inspector=Field<ConfigurationInspector>(main,"machineInspector");var disclosure=All(main).OfType<ConfigurationDisclosure>().Single();Check(!disclosure.Expanded,"configuration starts collapsed");disclosure.Expanded=true;Application.DoEvents();Check(disclosure.Expanded&&inspector.Visible&&inspector.Width>0,"configuration opens with existing editor and data");disclosure.Expanded=false;Application.DoEvents();Check(!disclosure.Expanded,"configuration closes without changing data");Check(All(main).OfType<StateStage>().Single().Contains(Field<FlowLayoutPanel>(main,"actions")),"existing VM actions belong to the state stage");Check(All(main).OfType<FieldInput>().Single(x=>x.AccessibleName=="Поиск машин").Visible,"search stays available");Save(main,Path.Combine(output,"html-network.png"));
            tabs.SelectedIndex=2;Wait(main);Check(All(main).OfType<LiveLogsView>().Count()==1,"live log uses an embedded user control");
