            Call(main,"SelectVm","second");Wait(main);Check(All(main).OfType<LiveLogsView>().Count()==2&&All(main).OfType<LiveLogsView>().Count(v=>v.Visible)==1,"machine switch retains only one previous inactive log");
            tabs.SelectedIndex=0;foreach(string state in new[]{"stopped","running","paused","error"}){main.ApplyStates(J.O("second",state,"test","stopped"));Application.DoEvents();var stage=All(main).OfType<StateStage>().Single();Save(main,Path.Combine(output,"html-vm-"+state+".png"));File.WriteAllLines(Path.Combine(output,"actions-"+state+".txt"),All(stage).Where(c=>c.Visible).Select(c=>c.GetType().Name+" | "+c.Text+" | bounds="+c.Bounds+" | client="+c.ClientSize+" | parent="+c.Parent.GetType().Name+" "+c.Parent.ClientSize+" | auto="+c.AutoSize+" | margin="+c.Margin));CheckActions(main,state);Save(main,Path.Combine(output,"html-vm-"+state+".png"));}
            main.ClientSize=new System.Drawing.Size(920,680);Application.DoEvents();Check(All(main).OfType<InspectorWorkspace>().All(x=>x.Controls.Cast<Control>().Where(c=>c.Visible).All(c=>c.Width>0&&c.Height>0)),"narrow workspace retains usable content");
            CheckActions(main,"narrow");Save(main,Path.Combine(output,"html-vm-narrow.png"));main.Close();
        }
