        using(var demo=new MainWindow(root,null,true,false)){demo.Demo();demo.Show();Application.DoEvents();Save(demo,Path.Combine(output,"preview-main.png"));Field<LibraryModeSwitch>(demo,"libraryMode").Checked=true;typeof(MainWindow).GetField("selectedStand",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(demo,J.O("id","test-stand","name","Research laboratory","members",new[]{"ubuntu-server","kali"}));Call(demo,"ShowStand");Application.DoEvents();Check(All(demo).OfType<StateStage>().Any(x=>x.Visible),"stand overview uses the shared state layout");Check(All(demo).OfType<ConfigurationDisclosure>().Any(x=>x.Visible),"stand configuration remains available");Check(Field<Label>(demo,"standStateText").Text=="MIXED","paused and stopped members retain a mixed state");var disclosure=All(demo).OfType<ConfigurationDisclosure>().Single(x=>x.Visible);disclosure.Expanded=true;Application.DoEvents();Check(All(Field<ConfigurationInspector>(demo,"standInspector")).OfType<Button>().Any(x=>x.Visible&&x.Text=="Сеть и соединения"),"existing stand network action is available in configuration");disclosure.Expanded=false;demo.ApplyStates(J.O("ubuntu-server","checking","kali","stopped"));Application.DoEvents();Check(Field<Label>(demo,"standStateText").Text=="CHECKING","unconfirmed members cannot appear stopped");demo.ApplyStates(J.O("ubuntu-server","stopped","kali","stopped"));Save(demo,Path.Combine(output,"html-stand-structure.png"));demo.Close();}
        Check(before.SequenceEqual(File.ReadAllBytes(Path.Combine(root,"machines","test.json"))),"opening switching and closing tools preserves VM configuration");File.WriteAllText(Path.Combine(output,"html-workspace-results.txt"),"PASS: embedded tools, reuse, disposal, narrow layout, no configuration mutation");return 0;
